/* 测试：实际Session/Ledger奖励批次；防通知早于world/receipt、失败留半批、容量不足吞物、类型恢复丢失。
 * Unity/角色外壳沿COM01纯宿主夹具，不代签真实Editor攻击、物理落点或F输入。 */
using System;using System.Linq;using System.Reflection;using Ossastra.Inventory;using Ossastra.Characters;using Ossastra.CharacterCore;using UnityEngine;
static class InventorySeamsTests
{
 static int passed,failed;
 static void Require(bool value,string reason){if(!value)throw new Exception(reason);}
 static void Test(string name,Action body){try{body();Console.WriteLine("PASS "+name);passed++;}catch(Exception e){Console.WriteLine("FAIL "+name+": "+e.GetBaseException().Message);failed++;}}
 static void Set(object o,string n,object v)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);
 static InventorySession Setup(){var s=new InventorySession();var c=new CharacterControlCoordinator();foreach(var id in new[]{"hero","partner"}){var a=new CharacterRoot{ActorId=id};a.components[typeof(CharacterEquipment)]=new CharacterEquipment{State=new EquipmentState(id,100)};c.Characters.Add(a);}c.Current=c.Characters[0];Set(s,"coordinator",c);Set(s,"catalog",new[]{new ItemDefinitionSO{definitionId="ore",displayName="矿石",maxStack=20},new ItemDefinitionSO{definitionId="fiber",displayName="纤维",maxStack=20}});Set(s,"chest",new Transform());typeof(InventorySession).GetMethod("Start",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(s,null);Require(s.Ready,s.LastResult);return s;}
 static InventoryResult Reward(InventorySession s,string id,Action publish,InventoryContainerGrant[] grants=null){var method=typeof(InventorySession).GetMethod("CommitGroundReward");Require(method!=null,"natural reward API is absent");return(InventoryResult)method.Invoke(s,new object[]{id,"fixture-map",new Vector3(1,0,0),"floor:a","资源掉落",grants??new[]{new InventoryContainerGrant("ore",7)},publish});}
 static bool Loose(InventorySession s,string id){var m=typeof(InventorySession).GetMethod("IsLoosePickup");Require(m!=null,"typed loose pickup API absent");return(bool)m.Invoke(s,new object[]{id});}
 static void Main(){
 Test("observer capture sees ledger world metadata and receipt in one commit",()=>{var s=Setup();bool receipt=false;int calls=0;s.Ledger.Changed+=()=>{calls++;var snap=s.CaptureRuntimeState();Require(receipt&&snap.worldContainers.Any(r=>r.id=="drop:resource:a")&&s.Ledger.Items.Sum(i=>i.Quantity)==7,"mixed aggregate observed");};var q=Reward(s,"drop:resource:a",()=>receipt=true);Require(q.Ok&&receipt&&calls==1&&s.Ledger.NotificationErrorCount==0,"missing or intermediate atomic notification");Require(Loose(s,"drop:resource:a"),"natural reward misclassified as box");});
 Test("throwing publisher leaves no items world record revision or notification",()=>{var s=Setup();var revision=s.Ledger.MutationRevision;int calls=0;s.Ledger.Changed+=()=>calls++;bool thrown=false;try{Reward(s,"drop:resource:b",()=>throw new InvalidOperationException("injected publication failure"));}catch(TargetInvocationException){thrown=true;}Require(thrown&&calls==0&&s.Ledger.MutationRevision==revision&&s.Ledger.Container("drop:resource:b")==null&&!s.CaptureRuntimeState().worldContainers.Any(r=>r.id=="drop:resource:b")&&s.Ledger.Items.Length==0,"failed publication retained partial authority");});
 Test("unknown definition rejects entire reward before publisher",()=>{var s=Setup();bool receipt=false;var q=Reward(s,"drop:resource:c",()=>receipt=true,new[]{new InventoryContainerGrant("ore",2),new InventoryContainerGrant("unknown",1)});Require(!q.Ok&&!receipt&&s.Ledger.Items.Length==0&&s.Ledger.Container("drop:resource:c")==null&&!s.WorldContainerIds.Contains("drop:resource:c"),"invalid batch partially granted");});
 Test("full team leaves same ground stack then complete pickup succeeds",()=>{var s=Setup();Require(s.Ledger.Grant("team","fiber",200).Ok,"full backpack fixture");bool receipt=false;Require(Reward(s,"drop:resource:d",()=>receipt=true).Ok&&receipt,"reward fixture");var drop=s.Ledger.Items.Single(i=>i.Location.ContainerId=="drop:resource:d");Require(!s.Move(s.Ledger.Plan(drop.Id,"team")).Ok&&s.Ledger.Find(drop.Id).Quantity==7,"full backpack swallowed ground");var fill=s.Ledger.Items.First(i=>i.Location.ContainerId=="team");var execution=Guid.NewGuid();Require(s.Ledger.Reserve(fill.Id,20,execution).Ok&&s.Ledger.CommitConsumption(execution).Ok,"space fixture");Require(s.Move(s.Ledger.Plan(drop.Id,"team")).Ok,"complete pickup rejected");s.ReclaimEmptyGround();Require(s.Ledger.Find(drop.Id).Location.ContainerId=="team"&&!s.GroundContainers.Contains("drop:resource:d")&&s.Ledger.Items.Where(i=>i.DefinitionId=="ore").Sum(i=>i.Quantity)==7,"pickup count/cleanup wrong");});
 Test("typed natural surface survives capture and detached restore",()=>{var s=Setup();Require(Reward(s,"drop:resource:e",()=>{}).Ok,"fixture");var snapshot=s.CaptureRuntimeState();var row=snapshot.worldContainers.Single(r=>r.id=="drop:resource:e");Require((string)row.GetType().GetField("surfaceId").GetValue(row)=="floor:a","surface absent");Require(s.RestoreRuntimeState(snapshot,out var error),error);Require(Loose(s,row.id)&&s.ContainerPosition(row.id).Value.x==1,"typed restored ground inaccessible");s.SetActiveMap("other");Require(!s.GroundContainers.Contains(row.id)&&s.Ledger.Items.Sum(i=>i.Quantity)==7,"unload discarded items");s.SetActiveMap("fixture-map");Require(s.GroundContainers.Contains(row.id)&&s.Ledger.Items.Sum(i=>i.Quantity)==7,"return regranted items");});
 Test("save edit failure defers new reward without invoking receipt",()=>{var s=Setup();s.ConfigureEditGate(()=>false);bool receipt=false;var q=Reward(s,"drop:resource:f",()=>receipt=true);Require(!q.Ok&&!receipt&&s.Ledger.Items.Length==0,"save failure allowed new economic reward");s.ConfigureEditGate(null);Require(Reward(s,"drop:resource:f",()=>receipt=true).Ok&&receipt&&s.Ledger.Items.Sum(i=>i.Quantity)==7,"retry same intent failed");});
 Console.WriteLine("TOTAL passed="+passed+" failed="+failed);Environment.ExitCode=failed==0?0:1;
 }
}